test_that("all axes restore canonical order", {x<-matrix(1:6,2,3,dimnames=list(c("s2","s1"),c("m3","m1","m2")));expect_identical(colnames(align_markers(x,c("m1","m2","m3"),2)),c("m1","m2","m3"));expect_identical(rownames(align_samples(x,c("s1","s2"))),c("s1","s2"));expect_identical(colnames(align_traits(x,c("m1","m2","m3"))),c("m1","m2","m3"))})
test_that("alignment rejects ambiguous identities", {x<-setNames(1:3,c("a","b","c"));expect_error(align_markers(x,c("a","z")),"Missing");expect_error(align_markers(x,c("a","b")),"extra");expect_equal(unname(align_markers(x,c("b","a"),allow_extra=TRUE)),c(2,1));expect_error(align_markers(unname(x),c("a","b","c")),"Unnamed");names(x)[2]<-"a";expect_error(align_markers(x,c("a","c")),"unique")})
